const results = [];

for (const item of $input.all()) {

  let reply = "";
  const output = item.json?.output;

  if (!output || output.toString().trim() === "") {
    continue;
  }

  let raw = output.toString().trim();

  // Remove markdown fences
  raw = raw.replace(/```json|```/g, "").trim();

  // 🔴 FIX: remove wrapping quotes if present
  if (
    (raw.startsWith('"') && raw.endsWith('"')) ||
    (raw.startsWith("'") && raw.endsWith("'"))
  ) {
    raw = raw.slice(1, -1);
  }

  // Try JSON parse only if it really looks like JSON
  if (raw.startsWith("{") && raw.endsWith("}")) {
    try {
      const parsed = JSON.parse(raw);
      reply = parsed.reply ?? "";
    } catch {
      reply = raw;
    }
  } else {
    reply = raw;
  }

  reply = reply
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+\n/g, "\n")
    .trim();

  if (!reply) continue;

  results.push({
    json: {
      reply
    }
  });
}

return results;

const items = $input.all();

return items.map(item => {
  let rawText = item.json.output?.[0]?.content?.[0]?.text || "";

  // Remove markdown code block if present
  rawText = rawText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  let parsed = {};

  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    parsed = {};
  }

  return {
    json: {
      type: parsed.type || "",
      value: parsed.value || ""
    }
  };
});

